oxy_webhelp_navlinks = {"tocId-d39536e62106":{"topics":[{"title":"Microsoft Copilot Studio deployed in <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> reads Microsoft Copilot Studio agents and conversation         transcripts through the Dataverse API and, when you enable tool blocking, intercepts tool         calls in real time through the external threat detection integration of Copilot         Studio.<\/p>","href":"agent_cloud\/ms_copilot_studio_agent_operations.html","attributes":{"data-id":"ms_copilot_studio_agent_operations"},"menu":{"hasChildren":false},"tocID":"ms_copilot_studio_agent_operations-d39536e62110","next":"ms_copilot_studio_agent_operations-d39536e62110"},{"title":"Microsoft Foundry deployed in <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> monitors AI agents in Microsoft Foundry by ingesting         activity logs from Azure Application Insights through an app registration         connection.<\/p>","href":"agent_cloud\/foundry_deployed_agent_cloud.html","attributes":{"data-id":"foundry_deployed_agent_cloud"},"menu":{"hasChildren":false},"tocID":"foundry_deployed_agent_cloud-d39536e62228","next":"foundry_deployed_agent_cloud-d39536e62228"},{"title":"Google Cloud Gemini Enterprise in <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> uses a Google Cloud service account that you create to discover agents and read their conversation sessions in a Google Cloud project, covering both Gemini Enterprise and Gemini Enterprise Agent Platform (Vertex AI Agent Engine).<\/p>","href":"agent_cloud\/gemini_agent_operations.html","attributes":{"data-id":"gemini_agent_operations"},"menu":{"hasChildren":false},"tocID":"gemini_agent_operations-d39536e62375","next":"gemini_agent_operations-d39536e62375"},{"title":"AWS Bedrock Agents deployed in <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> reads Amazon Bedrock model invocation logs from Amazon CloudWatch Logs or an Amazon S3 bucket, through an IAM role in your AWS account that <span class=\"ph\">Agent Cloud<\/span> assumes.<\/p>","href":"agent_cloud\/aws_bedrock_agent_operations.html","attributes":{"data-id":"aws_bedrock_agent_operations"},"menu":{"hasChildren":false},"tocID":"aws_bedrock_agent_operations-d39536e62439","next":"aws_bedrock_agent_operations-d39536e62439"},{"title":"Amazon Bedrock AgentCore deployed in <span class=\"ph\">Agent Cloud<\/span>","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">Agent Cloud<\/span> reads the OpenTelemetry runtime logs that Amazon Bedrock AgentCore writes to Amazon CloudWatch, through an IAM role in your AWS account that <span class=\"ph\">Agent Cloud<\/span> assumes.<\/p>","href":"agent_cloud\/aws_bedrock_agentcore_agent_cloud.html","attributes":{"data-id":"aws_bedrock_agentcore_agent_cloud"},"menu":{"hasChildren":false},"tocID":"aws_bedrock_agentcore_agent_cloud-d39536e62495","next":"aws_bedrock_agentcore_agent_cloud-d39536e62495"}]}};